+import { claimNext } from "./jobs.ts";
+import { pool } from "./pool.ts";
+
+export interface JobApiResponse {
+  job: { id: string; payload: string } | null;
+}
+
+export const claimJobHandler = async (req: Request): Promise<Response> => {
+  if (req.method !== "GET") {
+    return new Response(JSON.stringify({ error: "Method not allowed" }), {
+      status: 405,
+      headers: { "Content-Type": "application/json" },
+    });
+  }
+
+  try {
+    const job = await claimNext();
+    return new Response(JSON.stringify({ job }), {
+      status: 200,
+      headers: { "Content-Type": "application/json" },
+    });
+  } catch (error) {
+    console.error("Error claiming job:", error);
+    return new Response(JSON.stringify({ error: "Internal server error" }), {
+      status: 500,
+      headers: { "Content-Type": "application/json" },
+    });
+  }
+};
+
+export const completeJobHandler = async (req: Request): Promise<Response> => {
+  if (req.method !== "POST") {
+    return new Response(JSON.stringify({ error: "Method not allowed" }), {
+      status: 405,
+      headers: { "Content-Type": "application/json" },
+    });
+  }
+
+  try {
+    const body = await req.json();
+    const jobId = body.jobId;
+
+    if (!jobId) {
+      return new Response(
+        JSON.stringify({ error: "jobId is required" }),
+        {
+          status: 400,
+          headers: { "Content-Type": "application/json" },
+        },
+      );
+    }
+
+    await pool.query("UPDATE jobs SET status = 'done' WHERE id = $1", [jobId]);
+
+    return new Response(JSON.stringify({ success: true }), {
+      status: 200,
+      headers: { "Content-Type": "application/json" },
+    });
+  } catch (error) {
+    console.error("Error completing job:", error);
+    return new Response(JSON.stringify({ error: "Internal server error" }), {
+      status: 500,
+      headers: { "Content-Type": "application/json" },
+    });
+  }
+};
